#!/usr/bin/env python3
"""Apply the soil-classification popup localization to an existing map.js.

Run from the repository root; edits static/js/map.js and makes a .bak backup.
"""
from pathlib import Path
import argparse
import difflib

ROOT = Path(__file__).resolve().parent

INSERT_AFTER = "  const cfg = window.ECHOREPO_CFG || {};\n"
INSERT_CODE = r'''

  // Soil classifications are fixed Flutter choices, not free-text translations.
  // Generated by tools/normalize_soil_classifications.py from Dart dictionaries.
  let soilClassifications = null;
  const SOIL_I18N_URL = cfg.soil_classifications_url || '/static/soil_classifications_i18n.json';
  const SOIL_LOCALE = String(
    cfg.current_locale || window.I18N?.locale || document.documentElement.lang || 'en'
  ).replace('-', '_');

  function normalizeSoilChoice(value) {
    return String(value ?? '').normalize('NFKC').trim().replace(/\s+/g, ' ').toLowerCase();
  }

  function getSoilLocaleDict(field) {
    const all = soilClassifications?.locales || {};
    const wanted = SOIL_LOCALE.toLowerCase();
    if (all[SOIL_LOCALE]?.[field]) return all[SOIL_LOCALE][field];
    const exact = Object.keys(all).find(k => k.toLowerCase() === wanted);
    if (exact) return all[exact]?.[field] || {};
    const language = wanted.split('_')[0];
    const preferred = language === 'el' ? 'el_GR' : language === 'nb' || language === 'no' ? 'nb_NO' : '';
    if (preferred && all[preferred]) return all[preferred]?.[field] || {};
    const match = Object.keys(all).find(k => k.toLowerCase().split('_')[0] === language);
    return match ? all[match]?.[field] || {} : {};
  }

  function localizeSoilChoice(field, englishValue, originalValue) {
    const raw = englishValue || originalValue;
    if (!raw) return raw;
    // Use either standardized *_en or original mobile-app choice for legacy /my.
    const lookup = soilClassifications?.reverse?.[field] || {};
    const key = lookup[normalizeSoilChoice(englishValue)] ||
                lookup[normalizeSoilChoice(originalValue)];
    if (!key) return raw; // No invented translation for unknown values.
    if (key === 'Other *' && SOIL_LOCALE.toLowerCase().startsWith('en')) return 'Other';
    const translated = getSoilLocaleDict(field)[key];
    return translated || soilClassifications?.english?.[field]?.[key] || raw;
  }

  fetch(SOIL_I18N_URL, { credentials: 'same-origin', cache: 'no-cache' })
    .then(response => {
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      return response.json();
    })
    .then(data => {
      if (!data || data.schema_version !== 1 || !data.reverse || !data.locales) {
        throw new Error('Unsupported soil-classification dictionary');
      }
      soilClassifications = data;
      // If a popup opened before the tiny JSON finished loading, refresh it.
      if (typeof map?.eachLayer === 'function') {
        const refreshLayer = layer => {
          if (layer.feature && layer.getPopup?.()?.isOpen?.()) {
            const popup = layer.getPopup();
            popup.setContent(formatPopup(layer.feature, !!layer.__owner));
            setTimeout(() => initPopupTooltips(popup), 0);
          }
          if (typeof layer.eachLayer === 'function') layer.eachLayer(refreshLayer);
        };
        map.eachLayer(refreshLayer);
      }
    })
    .catch(error => console.warn('Soil classifications i18n unavailable:', error));
'''
# Important: JS const map is declared later! Async .then will run after script completes,
# so it is initialized by then. If DOM rendering aborts before map creation, catch logs.

OLD_VALUES = '''    const texture = pick(
      p.SOIL_TEXTURE_texture,
      p.soil_texture_en, p.soil_texture_orig,
      p.texture_en, p.texture_orig,
      p.texture
    );

    const structure = pick(
      p.SOIL_STRUCTURE_structure,
      p.soil_structure_en, p.soil_structure_orig,
      p.structure_en, p.structure_orig,
      p.structure
    );'''
NEW_VALUES = '''    const texture = localizeSoilChoice(
      'texture',
      pick(p.soil_texture_en, p.texture_en),
      pick(p.soil_texture_orig, p.SOIL_TEXTURE_texture, p.texture_orig, p.texture)
    );

    const structure = localizeSoilChoice(
      'structure',
      pick(p.soil_structure_en, p.structure_en),
      pick(p.soil_structure_orig, p.SOIL_STRUCTURE_structure, p.structure_orig, p.structure)
    );'''


def patch(txt):
    if 'function localizeSoilChoice(' not in txt:
        if txt.count(INSERT_AFTER) < 1:
            raise ValueError('ECHOREPO_CFG declaration not found in map.js')
        txt = txt.replace(INSERT_AFTER, INSERT_AFTER + INSERT_CODE, 1)
    if NEW_VALUES not in txt:
        if txt.count(OLD_VALUES) != 1:
            raise ValueError('Expected original texture/structure popup code not found (different map.js version?)')
        txt = txt.replace(OLD_VALUES, NEW_VALUES, 1)
    return txt


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--file', type=Path, default=Path('static/js/map.js'))
    parser.add_argument('--apply', action='store_true')
    args = parser.parse_args()
    path = args.file
    old = path.read_text(encoding='utf-8')
    new = patch(old)
    if new == old:
        print('Already patched; no changes')
        return
    print(''.join(difflib.unified_diff(old.splitlines(True), new.splitlines(True), fromfile=str(path), tofile=str(path))))
    if args.apply:
        path.with_suffix(path.suffix+'.soil-backup').write_text(old, encoding='utf-8')
        path.write_text(new, encoding='utf-8')
        print('Applied; backup:', path.with_suffix(path.suffix+'.soil-backup'))
    else:
        print('Preview only; re-run with --apply')


if __name__ == '__main__': main()
